import { test, expect, type Page, type Locator } from '@playwright/test';

class TodoPage {
  readonly list: Locator;
  readonly input: Locator;
  constructor(readonly page: Page) {
    this.list = page.getByRole('list', { name: 'Todo list' }).getByRole('listitem');
    this.input = page.getByLabel('New todo');
  }
  async goto() {
    await this.page.goto('/todos');
  }
  async add(title: string) {
    await this.input.fill(title);
    await this.page.getByRole('button', { name: 'Add' }).click();
  }
}

test('adds a todo via the page object', async ({ page }) => {
  const todos = new TodoPage(page);
  await todos.goto();
  await todos.add('Write page objects');
  await expect(todos.list).toHaveCount(4);
  await expect(todos.list.last()).toHaveText('Write page objects');
});
